head.b:skin:
:root{
  --bg:#f5f7fb; --surface:#ffffff; --ink:#111827; --body:#334155; --muted:#64748b;
  --line:#dbe4ee; --soft:#eef4fb; --blue:#2563eb; --blue-dark:#1e40af;
  --green:#0f766e; --amber:#b45309; --shadow:0 14px 35px rgba(15,23,42,.08);
  --radius:12px;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--body);font:400 16px/1.72 Arial,Helvetica,sans-serif;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
img{display:block;max-width:100%}
.wrap{max-width:1160px;margin:0 auto;padding:0 24px}
.topbar{background:#0f172a;color:#e5edf7;border-bottom:1px solid rgba(255,255,255,.08)}
.topbar .wrap{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.brand{display:flex;align-items:center;gap:12px;font-weight:800;font-size:20px}
.brand-mark{width:38px;height:38px;border-radius:10px;background:linear-gradient(135deg,#2563eb,#0f766e);display:grid;place-items:center;color:#fff;font-weight:900}
.nav{display:flex;gap:22px;align-items:center;font-size:14px;font-weight:700}
.nav a{color:#dbeafe}
.nav a:hover{color:#fff}
.hero{background:linear-gradient(135deg,#0f172a 0%,#172554 54%,#164e63 100%);color:#fff}
.hero .wrap{padding:48px 24px 42px;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(280px,.8fr);gap:34px;align-items:end}
.eyebrow{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#93c5fd}
.hero h1{margin:10px 0 12px;font-size:44px;line-height:1.08;color:#fff;letter-spacing:-.01em}
.hero p{margin:0;max-width:670px;color:#dbeafe;font-size:17px}
.hero-panel{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:var(--radius);padding:18px}
.hero-panel strong{display:block;color:#fff;margin-bottom:8px}
.hero-panel ul{margin:0;padding-left:18px;color:#dbeafe}
.hero-panel li{margin:4px 0}
.chips{padding:22px 0 0;display:flex;gap:10px;flex-wrap:wrap}
.chip{display:inline-flex;align-items:center;padding:8px 13px;border-radius:999px;background:#fff;border:1px solid var(--line);color:#1e3a8a;font-size:13px;font-weight:700}
.crawl-start{padding:24px 0 0}
.crawl-start h2{margin:0 0 12px;color:var(--ink);font-size:20px}
.crawl-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.crawl-grid a{display:flex;align-items:center;min-height:54px;padding:11px 13px;background:#fff;border:1px solid var(--line);border-radius:10px;color:#17335f;font-size:13px;font-weight:700;line-height:1.35}
.crawl-grid a:hover{border-color:#93c5fd;color:#1d4ed8}
.layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:30px;padding:30px 0 46px}
.section-title{display:flex;align-items:flex-end;justify-content:space-between;margin:0 0 16px}
.section-title h2{margin:0;color:var(--ink);font-size:24px;line-height:1.2}
.section-title span{color:var(--muted);font-size:13px}
.post-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow)}
.thumb{height:178px;background:linear-gradient(135deg,#dbeafe,#ecfeff);overflow:hidden}
.thumb img{width:100%;height:100%;object-fit:cover}
.thumb-empty{height:100%;display:grid;place-items:center;color:#1e3a8a;font-weight:800}
.card-body{padding:18px}
.label{display:inline-block;margin-bottom:10px;padding:4px 9px;border-radius:999px;background:#eff6ff;color:#1d4ed8;font-size:11px;font-weight:800;text-transform:uppercase}
.card h3{margin:0;color:var(--ink);font-size:19px;line-height:1.32}
.excerpt{margin:9px 0 0;color:var(--muted);font-size:14px;line-height:1.55}
.meta{margin-top:12px;color:#94a3b8;font-size:12px;font-weight:700}
.sidebar{display:flex;flex-direction:column;gap:18px}
.widget{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:20px;box-shadow:var(--shadow)}
.widget h3{margin:0 0 12px;color:var(--ink);font-size:15px;text-transform:uppercase;letter-spacing:.08em}
.widget p{margin:0;color:var(--muted);font-size:14px}
.quick-list{display:grid;gap:9px}
.quick-list a{display:block;padding:11px 12px;border-radius:10px;background:var(--soft);color:#17335f;font-weight:700;font-size:14px}
.page-links{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.page-links a{padding:10px;border:1px solid var(--line);border-radius:10px;color:#1e3a8a;font-weight:700;font-size:13px;text-align:center}
.search-box{display:flex;gap:8px}
.search-box input{min-width:0;flex:1;border:1px solid var(--line);border-radius:10px;padding:11px 12px;font-size:14px}
.search-box button{border:0;border-radius:10px;background:var(--blue);color:#fff;font-weight:800;padding:0 14px;cursor:pointer}
.post-shell{max-width:920px;margin:30px auto 50px;background:#fff;border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:28px}
.post-shell .post-body{max-width:860px;margin:0 auto}
.post-body h1{font-size:34px;line-height:1.18;color:var(--ink);margin:0 0 18px}
.post-body h2{font-size:25px;line-height:1.25;color:var(--ink);margin:36px 0 14px;padding-top:8px;border-top:1px solid var(--line)}
.post-body h3{font-size:20px;color:var(--ink);margin:22px 0 8px}
.post-body p{margin:0 0 18px}
.post-body a{color:var(--blue);font-weight:700;border-bottom:1px solid rgba(37,99,235,.28)}
.post-body img{border-radius:14px;border:1px solid var(--line);margin:20px 0}
.post-body table{width:100%;border-collapse:separate;border-spacing:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;margin:14px 0 24px}
.post-body th,.post-body td{padding:13px 15px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
.post-body th{background:#eff6ff;color:#17335f}
.post-body tr:last-child td{border-bottom:0}
.post-meta{margin:0 0 18px;color:#64748b;font-size:13px;font-weight:700}
.footer{background:#0f172a;color:#cbd5e1;margin-top:20px}
.footer .wrap{padding:28px 24px;display:grid;grid-template-columns:1fr auto;gap:20px;align-items:center}
.footer strong{display:block;color:#fff;font-size:18px;margin-bottom:4px}
.footer-links{display:flex;gap:14px;flex-wrap:wrap;font-size:13px;font-weight:700}
.blog-pager{display:flex;justify-content:center;gap:12px;margin:24px 0}
.blog-pager a{background:#fff;border:1px solid var(--line);border-radius:999px;padding:10px 16px;font-weight:700;color:#1e3a8a}
.quickedit,.widget-item-control,.Attribution,.comments,.comment-footer{display:none!important}
@media (max-width:920px){.hero .wrap,.layout{grid-template-columns:1fr}.post-grid{grid-template-columns:1fr}.crawl-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sidebar{display:grid;grid-template-columns:1fr 1fr}.hero h1{font-size:36px}}
@media (max-width:640px){.wrap{padding:0 18px}.topbar .wrap{align-items:flex-start;flex-direction:column;padding:16px 18px}.nav{flex-wrap:wrap;gap:12px}.hero .wrap{padding:34px 18px}.hero h1{font-size:31px}.crawl-grid{grid-template-columns:1fr}.sidebar{display:flex}.post-shell{margin:18px 12px 34px;padding:18px}.footer .wrap{grid-template-columns:1fr}}
